'use strict';

const fs = require('node:fs');
const path = require('node:path');
const official = require('./renderer/official-condition-text.js');
const {
  KdrgSearchService,
} = require('./src/kdrg-search-service');

const pkg = JSON.parse(
  fs.readFileSync('package.json', 'utf8'),
);

if (pkg.version !== '0.5.13') {
  throw new Error(`package version ${pkg.version}`);
}

if (
  pkg?.build?.win?.icon
  !== 'renderer/assets/icon-kdrg-v47.ico'
) {
  throw new Error(
    `builder icon ${pkg?.build?.win?.icon}`,
  );
}

for (const relative of [
  'renderer/assets/icon-kdrg-v47.png',
  'renderer/assets/icon-kdrg-v47.ico',
]) {
  if (!fs.existsSync(relative)) {
    throw new Error(`icon missing ${relative}`);
  }
}

if (
  official.meta.schema_version
  !== 'kdrg-official-condition-text-v3-authority-overlay'
) {
  throw new Error('official overlay schema regression');
}

if (Object.keys(official.byAdrg).length !== 121) {
  throw new Error('official override count regression');
}

const p651 = official.byAdrg.P651?.text || '';
if (!p651.includes('시술명 table2을 제외한 OR procedure')) {
  throw new Error('P651 official wording regression');
}
if (/OR procedure\s+and not\(시술명 table2\)/.test(p651)) {
  throw new Error('P651 reconstructed wording leaked');
}

const f022 = official.byAdrg.F022;
if (
  !f022
  || f022.source_kind !== 'OFFICIAL_CORRECTION_20260731'
  || f022.text !==
    '(시술명 table2 and 시술명 table 3) or 시술명 table6'
) {
  throw new Error('F022 correction regression');
}

const app = fs.readFileSync('renderer/app.js', 'utf8');
const index = fs.readFileSync('renderer/index.html', 'utf8');

if (!app.includes('officialConditionDisplayText(detail)')) {
  throw new Error('source-first renderer regression');
}

if (
  index.indexOf('official-condition-text.js') < 0
  || index.indexOf('official-condition-text.js')
    >= index.indexOf('app.js')
) {
  throw new Error('official module load-order regression');
}

const service = new KdrgSearchService(
  path.resolve(
    '..',
    'data',
    'kdrg_v47_search_integrated_v3.json',
  ),
);

const p6510 = service.getDetail('AADRG', 'P6510').detail;
if (!p6510 || p6510.adrg !== 'P651' || !p6510.condition_ast) {
  throw new Error('P6510 inheritance regression');
}

console.log('[PASS] Stage65D source + icon release-prep probe');
